from pathlib import Path
p=Path('scripts/studies/visual-quality.cjs');s=p.read_text();s=s.replace('if(request.treeStudy)await captureTreeDiagnostics(p,dir);','if(request.treeStudy)await captureTreeDiagnostics(p,dir);if(request.grassDetail)await captureGrassDetail(p,dir);')
pos=s.index('async function startSession()')
s=s[:pos]+'''// A real near-ground camera, derived from a selected instance; no scene regeneration or hidden material swap.
async function captureGrassDetail(page,dir){
 const d=await page.evaluate(()=>{const {r,s,c}=window.__visual,position=c.position.clone(),quaternion=c.quaternion.clone();const batches=[];s.traverse(o=>{if(o.isInstancedMesh&&o.name==='lab-savanna-grass'&&o.visible)batches.push(o);});const near=batches[batches.length-1];if(!near)return null;const a=near.instanceMatrix.array;let best=0,score=Infinity;for(let i=0;i<near.count;i++){const t=(a[i*16+12]-6)**2+(a[i*16+14]-31)**2;if(t<score){score=t;best=i;}}const k=best*16,x=a[k+12],y=a[k+13],z=a[k+14];c.position.set(x+1.4,y+.8,z+2.6);c.lookAt(x,y+.35,z);c.updateMatrixWorld();r.render(s,c);const result={png:r.domElement.toDataURL(),camera:{position:c.position.toArray(),quaternion:c.quaternion.toArray()},batches:batches.map(o=>({count:o.count,trianglesPerInstance:(o.geometry.index?.count??o.geometry.attributes.position.count)/3,alphaTest:o.material.alphaTest,transparent:o.material.transparent,castShadow:o.castShadow,receiveShadow:o.receiveShadow})),calls:r.info.render.calls,triangles:r.info.render.triangles,overdraw:{hardwareMeasured:false,alphaCoverage:'No alpha test or transparency for dimensional grass; opaque depth-tested geometry, not a claim of zero fragment overdraw.'}};c.position.copy(position);c.quaternion.copy(quaternion);c.updateMatrixWorld();return result;});if(d){fs.writeFileSync(dir+'/grass-detail.png',Buffer.from(d.png.split(',')[1],'base64'));delete d.png;fs.writeFileSync(dir+'/grass-detail.json',JSON.stringify(d,null,2));}
}
''' +s[pos:];p.write_text(s)
